using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace ForgeScope.Workbench;

public static class Program
{
    static string H(object? value)=>HtmlEncoder.Default.Encode(value?.ToString()??"");
    static string Text(JsonElement e,string name)=>e.TryGetProperty(name,out var v)?v.ToString():"";
    static JsonElement[] Items(JsonElement e,string name)=>e.TryGetProperty(name,out var v)&&v.ValueKind==JsonValueKind.Array?v.EnumerateArray().ToArray():[];
    static readonly string Css="""
        :root{color-scheme:dark;--bg:#0b1018;--card:#131d2a;--line:#2b3c50;--text:#edf3f9;--mint:#a5edb1;--muted:#abbacd}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui}body.light{color-scheme:light;--bg:#f4f7f9;--card:#fff;--line:#cedbe4;--text:#152238;--mint:#287640;--muted:#4d6178}header{padding:22px 4vw;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px}.brand{font-size:24px;font-weight:800}.brand span{color:var(--mint)}.muted{color:var(--muted)}main{max-width:1450px;margin:auto;padding:30px 4vw}h1{font-size:clamp(30px,4vw,48px);letter-spacing:-1.7px}h2{font-size:19px}h3{font-size:16px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:25px 0}.card,.stat{padding:22px;background:var(--card);border:1px solid var(--line);border-radius:12px}.stat strong{display:block;font-size:32px}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:20px}.wide{grid-column:1/-1}form{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:16px 0}input,select,button{padding:10px 13px;border-radius:7px;border:1px solid var(--line);background:var(--card);color:var(--text);font:inherit}button{cursor:pointer}a,code{color:var(--mint);overflow-wrap:anywhere}p{line-height:1.6}.chain{border-left:2px solid var(--mint);padding:8px 12px;margin:10px 0}.pill{font-size:11px;display:inline-block;padding:4px 8px;border:1px solid var(--line);border-radius:4px;margin-right:6px}.finding{border-top:1px solid var(--line);padding:16px 0}.scroll{max-height:500px;overflow:auto}summary{cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere}.exports{margin-left:auto;display:flex;gap:15px}footer{font-size:12px;color:var(--muted);padding:30px 0}.badge{color:var(--mint);letter-spacing:2px;text-transform:uppercase;font-size:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.exports{margin-left:0}header{flex-wrap:wrap}}
        """;
    public static string Render(JsonElement r,string query,string engine,string seed,string language,string theme,string? nonce,bool canScan)
    {
        language=Localization.Language(language);string T(string en,string br)=>Localization.Get(en,language);string L(string text)=>Localization.Get(text,language);var impact=r.GetProperty("impact");var b=new StringBuilder("<!doctype html><html lang=\""+language+"\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>ForgeScope · Java + .NET</title>"+BrandAssets.Head+"<style>"+Localization.ReadResource("viewer.css")+Css+"</style><body class=\""+(theme=="light"?"light":"dark")+"\"><header><div class=\"brand\">Forge<span>Scope</span></div><span class=\"muted\">Java 21 + C#/.NET 10</span><nav class=\"exports\"><a href=\"/report.json\">JSON</a><a href=\"/report.sarif\">SARIF</a></nav></header><main id=\"overview\">");
        b.Append("<div class=\"badge\">").Append(T("Local investigation workbench","Painel local de investigação")).Append("</div><h1>").Append(T("Understand the change. Follow the evidence.","Entenda a mudança. Siga as evidências.")).Append("</h1><p class=\"muted\">").Append(H(Text(r,"project"))).Append(" · ").Append(T("Source impact, diff review, CI diagnosis and maintenance.","Impacto no código, revisão de diff, diagnóstico de CI e manutenção.")).Append("</p>");
        b.Append("<div class=\"actions\"><a class=\"button primary\" href=\"#tour-1\">").Append(H(L("Start demonstration"))).Append(" →</a></div>");
        b.Append("<form method=\"get\"><label>").Append(T("Search evidence","Pesquisar evidências")).Append(" <input name=\"q\" value=\"").Append(H(query)).Append("\"></label><label>").Append(T("Engine","Motor")).Append(" <select name=\"engine\">");
        foreach(var name in new[]{"all","impact","patchscope","cifuse","devrescue","reporelief"})b.Append("<option value=\"").Append(name).Append('"').Append(name==engine?" selected":"").Append('>').Append(name=="all"?T("All engines","Todos os motores"):name).Append("</option>");
        b.Append("</select></label><label>").Append(T("Start from","Começar por")).Append(" <select name=\"seed\">");
        var paths=Items(impact,"symbols").Select(s=>Text(s,"path")).Concat(Items(impact,"changed").Select(s=>s.ToString())).Distinct().Order().ToArray();
        if(string.IsNullOrEmpty(seed))seed=paths.FirstOrDefault(p=>p.EndsWith(".java",StringComparison.Ordinal)||p.EndsWith(".cs",StringComparison.Ordinal))??paths.FirstOrDefault()??"";
        foreach(var p in paths)b.Append("<option value=\"").Append(H(p)).Append('"').Append(p==seed?" selected":"").Append('>').Append(H(p)).Append("</option>");
        b.Append("</select></label><label>").Append(H(L("Language"))).Append(" <select name=\"lang\">");
        foreach(var (id,label) in new[]{("pt-BR","Português (Brasil)"),("en","English"),("es","Español")})b.Append("<option value=\"").Append(id).Append('"').Append(language==id?" selected":"").Append('>').Append(label).Append("</option>");
        b.Append("</select></label><label>").Append(H(L("Theme"))).Append(" <select name=\"theme\"><option value=\"dark\"").Append(theme!="light"?" selected":"").Append('>').Append(H(L("Dark"))).Append("</option><option value=\"light\"").Append(theme=="light"?" selected":"").Append('>').Append(H(L("Light"))).Append("</option></select></label><button>").Append(H(L("Apply filters"))).Append("</button></form>");
        if(canScan)b.Append("<section class=\"card\"><h2>").Append(T("Analyze the configured repository","Analisar o repositório configurado")).Append("</h2><form method=\"post\" action=\"/scan\"><input type=\"hidden\" name=\"nonce\" value=\"").Append(H(nonce)).Append("\"><input type=\"hidden\" name=\"lang\" value=\"").Append(language).Append("\"><input type=\"hidden\" name=\"theme\" value=\"").Append(theme=="light"?"light":"dark").Append("\"><label>").Append(H(L("Git base"))).Append(" <input name=\"base\" value=\"HEAD\" maxlength=\"200\"></label><label>").Append(T("Changed file (optional)","Arquivo alterado (opcional)")).Append(" <input name=\"changed\" maxlength=\"500\"></label><button>").Append(T("Run local analysis","Executar análise local")).Append("</button></form><p class=\"muted\">").Append(T("Runs the Java analyzer on the repository selected at startup. It does not run project builds or tests.","Executa o analisador Java no repositório definido ao iniciar. Não executa builds nem testes do projeto.")).Append("</p></section>");
        b.Append("<section class=\"overview\">").Append(Localization.Tour(1,language)).Append("<div class=\"stats\">");int[] counts={impact.GetProperty("modules").GetInt32(),Items(impact,"affected").Length,Items(impact,"test_candidates").Length,Items(r,"findings").Length};string[] labels={T("Source modules","Módulos fonte"),T("Changed / affected files","Arquivos alterados / afetados"),T("Test candidates","Testes candidatos"),T("Review findings","Sinais para revisão")};
        for(int i=0;i<counts.Length;i++)b.Append("<div class=\"stat\"><strong>").Append(counts[i]).Append("</strong><span class=\"muted\">").Append(labels[i]).Append("</span></div>");b.Append("</div></section><div class=\"grid\"><section class=\"card\">").Append(Localization.Tour(2,language)).Append("<h2>").Append(T("Dependency paths","Caminhos de dependência")).Append("</h2><p><code>").Append(H(seed)).Append("</code></p>");
        var reached=new HashSet<string>{seed};var queue=new Queue<string>();queue.Enqueue(seed);var chains=new Dictionary<string,List<JsonElement>>{{seed,[]}};var edges=Items(impact,"edges");
        while(queue.Count>0){var target=queue.Dequeue();foreach(var e in edges.Where(e=>Text(e,"target")==target)){var source=Text(e,"source");if(reached.Add(source)){chains[source]=[..chains[target],e];queue.Enqueue(source);}}}
        foreach(var (path,chain) in chains){b.Append("<div class=\"chain\"><strong>").Append(H(path)).Append("</strong>");foreach(var e in chain)b.Append("<div>").Append(H(Text(e,"source"))).Append(':').Append(H(Text(e,"line"))).Append(" → ").Append(H(Text(e,"target"))).Append("</div>");b.Append("</div>");}b.Append("</section><section class=\"card\">").Append(Localization.Tour(3,language)).Append("<h2>").Append(T("Tests to investigate","Testes para investigar")).Append("</h2>");
        foreach(var p in Items(impact,"test_candidates"))b.Append("<p><code>").Append(H(p)).Append("</code></p>");b.Append("<h2>").Append(T("Analysis engines","Motores de análise")).Append("</h2>");foreach(var e in r.GetProperty("engines").EnumerateObject())b.Append("<p>").Append(H(e.Name)).Append(" · ").Append(H(L(Text(e.Value,"status")))).Append("</p>");
        b.Append("</section><section class=\"card wide\">").Append(Localization.Tour(4,language)).Append("<h2>").Append(T("Local reference review","Revisão de referências locais")).Append("</h2>");foreach(var reference in Items(impact,"unresolved_references"))b.Append("<div class=\"chain\"><strong>").Append(H(Text(reference,"symbol"))).Append("</strong><div>").Append(H(Text(reference,"path"))).Append(':').Append(H(Text(reference,"line"))).Append(" → ").Append(H(Text(reference,"target"))).Append("</div><p>").Append(H(L(Text(reference,"reason")))).Append("</p></div>");
        b.Append("<h2>").Append(T("Source-resolved call candidates","Chamadas candidatas resolvidas no código")).Append("</h2><div class=\"scroll\">");foreach(var c in Items(impact,"calls").Take(500))b.Append("<div class=\"chain\"><strong>").Append(H(Text(c,"symbol"))).Append("</strong><div>").Append(H(Text(c,"source"))).Append(':').Append(H(Text(c,"line"))).Append(" → ").Append(H(Text(c,"target"))).Append("</div><small>").Append(H(Text(c,"caller"))).Append(" · ").Append(H(Text(c,"language"))).Append("</small></div>");
        b.Append("</div></section><section class=\"card wide\">").Append(Localization.Tour(5,language)).Append("<h2>").Append(T("Evidence and next steps","Evidências e próximos passos")).Append("</h2>");foreach(var f in Items(r,"findings").Where(f=>(engine=="all"||Text(f,"engine")==engine)&&(f.ToString()+L(Text(f,"title"))+L(Text(f,"action"))).Contains(query,StringComparison.OrdinalIgnoreCase)))
        {b.Append("<article class=\"finding\"><span class=\"pill\">").Append(H(Text(f,"engine"))).Append("</span><span class=\"pill\">").Append(H(L(Text(f,"priority")))).Append("</span><h3>").Append(H(L(Text(f,"title")))).Append("</h3><code>").Append(H(Text(f,"path"))).Append(':').Append(H(Text(f,"line"))).Append("</code><details><summary>").Append(T("Evidence & action","Evidência e ação")).Append("</summary><p>").Append(Evidence(f,language)).Append("</p><p>").Append(H(L(Text(f,"action")))).Append("</p></details></article>");}
        b.Append("</section><section class=\"card wide\">").Append(Localization.Tour(6,language)).Append("<h2>").Append(T("Coverage and limits","Cobertura e limites")).Append("</h2>");foreach(var v in Items(r,"limitations"))b.Append("<p class=\"muted\">").Append(H(L(v.ToString()))).Append("</p>");b.Append("<details><summary>").Append(T("Compiler diagnostics","Diagnósticos dos compiladores")).Append("</summary><pre>").Append(H(impact.GetProperty("warnings"))).Append("</pre></details></section></div><footer>ForgeScope 0.3.0 · Java + .NET · ").Append(T("All interactive application logic is C# server-side. No custom JavaScript.","A lógica interativa é C# no servidor local. Sem JavaScript próprio.")).Append("</footer></main></body></html>");return b.ToString();
    }
    static string Evidence(JsonElement f,string lang)
    {
        string evidence=Text(f,"evidence");
        if(Localization.Contains(evidence))return H(Localization.Get(evidence,lang));
        if(Text(f,"engine")=="impact"&&evidence.IndexOf(": ",StringComparison.Ordinal) is var split&&split>=0)return H(evidence[..split])+": "+H(Localization.Get(evidence[(split+2)..],lang));
        return "<span class=\"muted\">"+H(Localization.Get("Original source evidence",lang))+"</span><br><code>"+H(Localization.Get(evidence,lang))+"</code>";
    }
    public static bool TokenValid(string provided,string expected)=>CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(provided),Encoding.UTF8.GetBytes(expected));
    public static async Task<int> Main(string[] args)
    {
        if(args.Contains("--self-test"))return SelfTest();
        var options=new Dictionary<string,string>();for(int i=0;i<args.Length;i+=2){if(i+1>=args.Length)throw new ArgumentException("Expected --report PATH [--repo PATH --jar PATH --worker PATH --port 8765]");options[args[i]]=args[i+1];}
        var reportPath=Path.GetFullPath(options.GetValueOrDefault("--report",".forgescope/report.json"));
        var root=options.TryGetValue("--repo",out var repo)?Path.GetFullPath(repo):null;
        var jar=options.TryGetValue("--jar",out var j)?Path.GetFullPath(j):null;
        var worker=options.TryGetValue("--worker",out var w)?Path.GetFullPath(w):null;
        int port=int.Parse(options.GetValueOrDefault("--port","8765"),System.Globalization.CultureInfo.InvariantCulture);if(port<1024||port>65535)throw new ArgumentException("Port must be 1024–65535");
        var nonce=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));var gate=new SemaphoreSlim(1,1);
        var builder=WebApplication.CreateBuilder(new WebApplicationOptions{Args=[]});builder.WebHost.UseUrls($"http://127.0.0.1:{port}");builder.WebHost.ConfigureKestrel(k=>k.Limits.MaxRequestBodySize=16_384);
        var app=builder.Build();app.Use(async(ctx,next)=>{if(ctx.Request.Host.Host is not("127.0.0.1" or "localhost")){ctx.Response.StatusCode=400;return;}ctx.Response.Headers.ContentSecurityPolicy="default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'";ctx.Response.Headers.XContentTypeOptions="nosniff";await next();});
        async Task<JsonDocument?> ReadReport(){if(!File.Exists(reportPath))return null;var info=new FileInfo(reportPath);if(info.Length>30_000_000)throw new ArgumentException("Report exceeds 30 MB");return JsonDocument.Parse(await File.ReadAllTextAsync(reportPath));}
        app.MapGet("/",async(HttpContext ctx)=>{using var doc=await ReadReport();if(doc is null)return Results.Content(Localization.Get("Generate a Java report first, then reload this page.",ctx.Request.Query["lang"].ToString()),"text/plain",statusCode:404);return Results.Content(Render(doc.RootElement,ctx.Request.Query["q"].ToString(),ctx.Request.Query["engine"].FirstOrDefault()??"all",ctx.Request.Query["seed"].ToString(),Localization.Language(ctx.Request.Query["lang"].ToString()),ctx.Request.Query["theme"].ToString(),nonce,root is not null&&jar is not null),"text/html",Encoding.UTF8);});
        app.MapGet("/report.json",async()=>{using var doc=await ReadReport();return doc is null?Results.NotFound():Results.File(Encoding.UTF8.GetBytes(doc.RootElement.GetRawText()),"application/json","forgescope-report.json");});
        app.MapGet("/report.sarif",()=>{string path=Path.Combine(Path.GetDirectoryName(reportPath)!,"report.sarif");return File.Exists(path)?Results.File(path,"application/sarif+json","forgescope-report.sarif"):Results.NotFound();});
        app.MapGet("/favicon.ico",()=>BrandAssets.Get("favicon.ico"));
        app.MapGet("/assets/branding/{name}",(string name)=>BrandAssets.Get(name));
        app.MapGet("/health",()=>Results.Json(new{status="ok",runtime="C#/.NET 10",javaScanConfigured=root is not null&&jar is not null}));
        app.MapPost("/scan",async(HttpContext ctx)=>{
            if(root is null||jar is null)return Results.StatusCode(409);
            var origin=ctx.Request.Headers.Origin.ToString();if(origin.Length>0&&origin!=$"http://127.0.0.1:{port}"&&origin!=$"http://localhost:{port}")return Results.StatusCode(403);
            var form=await ctx.Request.ReadFormAsync();string lang=Localization.Language(form["lang"].ToString());if(!TokenValid(form["nonce"].ToString(),nonce))return Results.StatusCode(403);
            string baseline=form["base"].ToString(),changed=form["changed"].ToString();if(baseline.Length>200||baseline.StartsWith('-')||changed.Length>500)return Results.BadRequest(Localization.Get("Invalid scan input",lang));
            if(!await gate.WaitAsync(0))return Results.StatusCode(409);
            try{var start=new ProcessStartInfo("java"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add("-jar");start.ArgumentList.Add(jar);start.ArgumentList.Add(root);start.ArgumentList.Add("--output");start.ArgumentList.Add(Path.GetDirectoryName(reportPath)!);if(baseline.Length>0){start.ArgumentList.Add("--base");start.ArgumentList.Add(baseline);}if(changed.Length>0){start.ArgumentList.Add("--changed");start.ArgumentList.Add(changed);}if(worker is not null){start.ArgumentList.Add("--csharp-worker");start.ArgumentList.Add(worker);}using var process=Process.Start(start)!;var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(90));try{await process.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){process.Kill(entireProcessTree:true);return Results.Problem(Localization.Get("Java scan timed out",lang),statusCode:504);}await Task.WhenAll(stdout,stderr);if(process.ExitCode!=0)return Results.Problem(Localization.Get("Java scan failed. Review the local terminal and repository inputs.",lang),statusCode:422);return Results.Redirect("/?lang="+lang+"&theme="+(form["theme"]=="light"?"light":"dark"));}
            finally{gate.Release();}
        });
        Console.WriteLine($"ForgeScope local workbench: http://127.0.0.1:{port}");await app.RunAsync();return 0;
    }
    static int SelfTest()
    {
        using var doc=JsonDocument.Parse("""{"project":"<script>bad</script>","impact":{"modules":0,"symbols":[],"changed":[],"affected":[],"edges":[],"test_candidates":[],"unresolved_references":[],"calls":[],"warnings":[]},"findings":[],"engines":{},"limitations":[]}""");
        var es=Render(doc.RootElement,"","all","","es","dark",null,false);
        if(!es.Contains("lang=\"es\"",StringComparison.Ordinal)||!es.Contains("id=\"tour-6\"",StringComparison.Ordinal))throw new Exception("Spanish/tour rendering failed");
        var en=Render(doc.RootElement,"\"<script>","all","","en","dark","secret",true);var pt=Render(doc.RootElement,"","all","","pt","light",null,false);
        if(en.Contains("<script>",StringComparison.Ordinal)||!en.Contains("&lt;script&gt;",StringComparison.Ordinal))throw new Exception("HTML encoding failed");
        if(!pt.Contains("Painel local de investigação",StringComparison.Ordinal)||!pt.Contains("class=\"light\"",StringComparison.Ordinal))throw new Exception("PT/theme rendering failed");
        if(!TokenValid("abc","abc")||TokenValid("abc","def")||TokenValid("", "abc"))throw new Exception("CSRF token comparison failed");
        if(pt.Contains("action=\"/scan\"",StringComparison.Ordinal)||!en.Contains("action=\"/scan\"",StringComparison.Ordinal))throw new Exception("Read-only mode failed");
        Console.WriteLine("C# workbench: 10 encoding, locale, tour, theme, token and mode checks passed");return 0;
    }
}
